args.command:
cd /workspace/site && python3 - <<'EOF'
import re,os
files=['index.html','docs/getting-started.html','docs/faq.html']
graph={}
for f in files:
    s=open(f,encoding='utf-8').read()
    refs=re.findall(r'(?:href|src)="([^"]*)"',s)
    base=os.path.dirname(f)
    targets=set()
    bad=[]
    for r in refs:
        if r.startswith('#'):
            aid=r[1:]
            if f'id="{aid}"' not in s: bad.append(('anchor-missing',r))
            continue
        if re.match(r'^[a-zA-Z]+:',r) or r.startswith('//'):
            bad.append(('external',r)); continue
        p=os.path.normpath(os.path.join(base,r.split('#')[0]))
        if not os.path.exists(p): bad.append(('missing-file',r,p))
        else: targets.add(p)
    graph[f]=targets
    print(f, 'refs=',len(refs), 'problems=',bad)
print('--- reachability ---')
for f in files:
    others=[os.path.normpath(x) for x in files if x!=f]
    print(f,'->',[(o, o in graph[f]) for o in others], 'css=', os.path.normpath(os.path.join(os.path.dirname(f),'styles.css')) if False else ('styles.css' in [os.path.basename(t) for t in graph[f]]))
EOF
